        for node in nodes:
            for out_edge in node.out_edges:
                if out_edge in self.node_map:
                    self.node_map[out_edge].in_degree += 1
                else:
                    raise RuntimeError("Invalid graph: edge to non-existent node")

    def find_node(self, id: int):
        return self.node_map.get(id)

    def topological_sort(self) -> List[Node]:
        in_degree = {}
        for node in self.nodes:
            in_degree[node.id] = node.in_degree

        queue = [node for node in self.nodes if in_degree[node.id] == 0]
        result = []
        visited_count = 0

        while queue:
            node = queue.pop(0)
            result.append(node)
            visited_count += 1

            for neighbor_id in node.out_edges:
                neighbor = self.find_node(neighbor_id)
                if neighbor:
                    in_degree[neighbor_id] -= 1
                    if in_degree[neighbor_id] == 0:
                        queue.append(neighbor)

        if visited_count != len(self.nodes):
            raise RuntimeError("Graph contains a cycle")

        return result

