                else:
                    return '\n'.join([f"{i+1}. {item}" for i, item in enumerate(child_content)])
            elif element.name == 'ul':
                if len(child_content) > 5:
                    list_items = child_content[:5]
                    list_items.append(f"[see more](/see-more)")
                    return '\n'.join([f"- {item}" for item in list_items])
                else:
                    return '\n'.join([f"- {item}" for item in child_content])
            else:
                return ""

    def cleanup_newlines(s: str) -> str:
        return re.sub(r'\n\s*\n', '\n\n', s).strip()

    return cleanup_newlines('\n'.join(translate_element(element) for element in content))
